#include <cstdio>
#include <algorithm>
#include <iostream>

#define LL long long

#define REP(i, x, y) for (int i = x, _ = y; i <= _; i ++)
#define rep(i, x, y) for (int i = x, _ = y; i >= _; i --)

const int MAXP = 1e6 + 1e5, MOD = 1e9 + 7;

LL k, p;
int tot;
LL ans;
int vis[MAXP];
int val[MAXP];

void Mod(LL &x) { x = (x % MOD + MOD) % MOD; }

void Bfs(int x)
{
    ++ tot;
    int x0 = x;
    LL w = 1;
    do {
        vis[x] = true;
        x = x * k % p;
        w = w * k % p;
    } while (x != x0);
    Mod(ans *= (w == 1? p : 1));
}

void Solve()
{
    if (k == 0) {
        LL w = 1;
        REP (i, 1, p - 1)
            w = w * p % MOD;
        printf("%lld\n", w);
        return ;
    }
    ans = 1;
    REP (i, 0, p - 1)
        if (vis[i] == 0)
            Bfs(i);
    printf("%lld\n", ans);
}

int main()
{
    if (fopen("B.in", "r") != NULL) {
        freopen("B.in", "r", stdin);
        freopen("B.out", "w", stdout);
    }

    scanf("%lld%lld", &p, &k);
    Solve();

    return 0;
}

